// Generated by build-home-screen.mjs. Cache-first, so the game starts with the network off after one visit.
const CACHE = 'istinye-park-d4d694d90a40';
const FILES = [
  "./",
  "audio-pack.js",
  "fonts/Baloo2-latin-ext-503e7e.woff2",
  "fonts/Baloo2-latin-f5fe33.woff2",
  "fonts/JosefinSans-latin-bdad05.woff2",
  "fonts/JosefinSans-latin-ext-b5e6fb.woff2",
  "fonts/OFL-Baloo2.txt",
  "fonts/OFL-JosefinSans.txt",
  "icons/apple-touch-icon-180.png",
  "icons/icon-192.png",
  "icons/icon-512.png",
  "icons/icon-maskable-512.png",
  "index.html",
  "manifest.webmanifest",
  "sw.js",
  "vendor/three-LICENSE.txt",
  "vendor/three.min.js"
];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((cache) => cache.addAll(FILES)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((key) => key.startsWith('istinye-park-') && key !== CACHE).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  if (event.request.method !== 'GET') return;
  event.respondWith(caches.match(event.request, { ignoreSearch: true }).then((hit) => hit || fetch(event.request)));
});
